export const CHUNK_SECONDS = 90;
export const MAX_CHUNK_BYTES = 3_000_000;
// Only the PCM format generated by our browser encoder is accepted. Parse RIFF
// chunks rather than assuming a 44-byte header (FFmpeg also writes LIST chunks).
export function wavDuration(bytes: Uint8Array): number {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const text = (at: number, n: number) =>
    String.fromCharCode(...bytes.subarray(at, at + n));
  if (bytes.length < 44 || text(0, 4) !== "RIFF" || text(8, 4) !== "WAVE")
    throw new Error("Se esperaba audio WAV PCM.");
  let rate = 0;
  let samples = 0;
  for (let at = 12; at + 8 <= bytes.length;) {
    const length = view.getUint32(at + 4, true);
    const start = at + 8;
    if (start + length > bytes.length)
      throw new Error("El fragmento WAV está incompleto.");
    if (text(at, 4) === "fmt ") {
      if (
        length < 16 ||
        view.getUint16(start, true) !== 1 ||
        view.getUint16(start + 2, true) !== 1 ||
        view.getUint32(start + 4, true) !== 16000 ||
        view.getUint16(start + 14, true) !== 16 ||
        view.getUint16(start + 12, true) !== 2 ||
        view.getUint32(start + 8, true) !== 32000
      )
        throw new Error("El fragmento debe ser PCM mono de 16 kHz y 16 bits.");
      rate = 32000;
    }
    if (text(at, 4) === "data") samples += length;
    at = start + length + (length % 2);
  }
  const duration = samples / rate;
  if (
    !Number.isFinite(duration) ||
    duration <= 0 ||
    duration > CHUNK_SECONDS + 0.1
  )
    throw new Error("El fragmento supera los 90 segundos o está vacío.");
  return duration;
}
